CREATE TABLE IF NOT EXISTS public.control (
  id bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  turn_on boolean DEFAULT false,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  voltage real NOT NULL,
  current real NOT NULL,
  power real NOT NULL,
  energy real NOT NULL,
  timer_enable boolean NOT NULL DEFAULT false,
  turn_on_time integer NOT NULL,
  turn_off_time integer NOT NULL,
  CONSTRAINT control_pkey PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS public.energy_log (
  id integer GENERATED ALWAYS AS IDENTITY NOT NULL,
  voltage real NOT NULL,
  current real NOT NULL,
  power real NOT NULL,
  energy real NOT NULL,
  create_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT energy_log_pkey PRIMARY KEY (id)
);

